#[test]
fn single_bit_one_to_decimal() {
    let input_base = 2;
    let input_digits: Array<u32> = array![1];
    let output_base = 10;

    let expected_output = Result::Ok(array![1]);
    let result = rebase(input_digits, input_base, output_base);

    assert_eq!(result, expected_output);
}

